    icon: Icons.login,
  ),
  AddProviderPreset(
    key: 'copilot',
    name: 'GitHub Copilot',
    description: 'Account sign-in via device flow',
    icon: Icons.login,
  ),
  AddProviderPreset(
    key: 'codemie',
    name: 'CodeMie',
    description: 'Enterprise SSO sign-in',
    icon: Icons.security_outlined,
  ),
  AddProviderPreset(
    key: 'openai',
    name: 'OpenAI',
