  faui.AddProviderPreset preset,
  faui.ProviderRegistry registry,
) async {
  final provider = await faui.pushProviderEditor(
    context,
    registry,
    title: preset.name,
  );
  if (provider == null) return false;
  await _saveConnection(provider.baseUrl, provider.modelId, '');
  return true;
}

