    final providers =
        <({String name, String id, String baseUrl, String? kind})>[];
    if (registry != null) {
      for (final p in registry.providers) {
        providers.add((
          name: p.name,
          id: p.id,
          baseUrl: p.baseUrl,
          kind: p.kind,
        ));
      }
