  /// Creates a preset tile.
  const AddProviderPreset({
    required this.key,
    required this.name,
    required this.description,
    required this.icon,
    this.baseUrl,
    this.keyHelpUrl,
  });

  /// Stable identifier for the tile (routing key).
  final String key;

  /// Display name.
  final String name;

  /// One-line description shown under [name].
  final String description;

