  ),
  AddProviderPreset(
    key: 'dial',
    name: 'DIAL',
    description: 'EPAM DIAL Core — Api key + deployment',
    icon: Icons.cloud_outlined,
    baseUrl: 'https://ai-proxy.lab.epam.com',
  ),
  AddProviderPreset(
    key: 'kimi',
    name: 'Kimi Code',
    description: 'Kimi Code models — API key',
    icon: Icons.cloud_outlined,
    baseUrl: 'https://api.kimi.com/coding/v1',
