        providers.add((
          name: p.name,
          id: p.id,
          baseUrl: p.baseUrl,
          kind: p.kind,
        ));
      }
      for (final preset in hostedProviderPresets) {
        if (preset.baseUrl == null) continue;
        if (providers.any((p) => p.baseUrl == preset.baseUrl)) continue;
        if (!hostedProviderConnected(preset)) continue;
