    name: 'OpenAI',
    description: 'api.openai.com — API key',
    icon: Icons.cloud_outlined,
    baseUrl: 'https://api.openai.com/v1',
  ),
  AddProviderPreset(
    key: 'anthropic',
    name: 'Anthropic',
    description: 'api.anthropic.com — API key',
    icon: Icons.cloud_outlined,
    baseUrl: 'https://api.anthropic.com',
  ),
  AddProviderPreset(
