  AddProviderPreset(
    key: 'dial',
    name: 'DIAL',
    description: 'EPAM DIAL Core — Api key + deployment',
    icon: Icons.cloud_outlined,
    baseUrl: 'https://ai-proxy.lab.epam.com',
