  /// Display name.
  final String name;

  /// One-line description shown under [name].
  final String description;

  /// Leading icon.
  final IconData icon;

  /// Pre-fill base URL for key-based presets; `null` for auth-flow presets
  /// (CodeMie SSO, OpenRouter OAuth) and Custom.
